<?php
namespace App\Http\Controllers;
use App\Models\Division;use App\Models\ItemInventoryHeader;use App\Models\ItemInventoryTransaction;use App\Models\JmvInventoryAudit;use App\Models\JmvInventoryBalance;use App\Models\JmvInventoryLocation;use App\Models\JmvStockRequest;use App\Models\User;use App\Notifications\JmvInventoryNotification;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Notification;use Illuminate\Validation\Rule;use Illuminate\Validation\ValidationException;
class JmvStockRequestController extends Controller{
 public function index(){$executive=auth()->user()->isExecutiveViewer();abort_unless($executive||$this->can('jmv.inventory.requests.create')||$this->can('jmv.inventory.requests.approve'),403);$divisionId=$this->divisionId();$query=JmvStockRequest::with(['items.item','items.location','requester:id,name,lastname','department:id,name','approver:id,name,lastname'])->where('division_id',$divisionId);if(!$executive&&!$this->can('jmv.inventory.requests.approve')&&!$this->can('jmv.inventory.movements.manage'))$query->where('requested_by',auth()->id());return view('jmv.requests.index',['requests'=>$query->latest()->paginate(15),'items'=>ItemInventoryHeader::where('division_id',$divisionId)->where('status',true)->orderBy('item_name')->get(),'locations'=>JmvInventoryLocation::where('division_id',$divisionId)->where('is_active',true)->get(),'canCreate'=>!$executive&&$this->can('jmv.inventory.requests.create'),'canApprove'=>!$executive&&$this->can('jmv.inventory.requests.approve'),'canRelease'=>!$executive&&$this->can('jmv.inventory.movements.manage')]);}
 public function store(Request $r){$this->authorize('jmv.inventory.requests.create');$divisionId=$this->divisionId();$d=$r->validate(['item_id'=>['required',Rule::exists('item_inventory_header','id')->where(fn($q)=>$q->where('division_id',$divisionId)->where('status',true))],'location_id'=>['required',Rule::exists('jmv_inventory_locations','id')->where(fn($q)=>$q->where('division_id',$divisionId))],'quantity'=>'required|integer|min:1','purpose'=>'required|string|max:1000']);$record=DB::transaction(function()use($d,$divisionId){$record=JmvStockRequest::create(['division_id'=>$divisionId,'request_no'=>$this->code(),'requested_by'=>auth()->id(),'department_id'=>auth()->user()->department_id,'status'=>'PENDING','purpose'=>$d['purpose']]);$record->items()->create(['item_inventory_header_id'=>$d['item_id'],'location_id'=>$d['location_id'],'quantity'=>$d['quantity']]);return $record;});$this->notify('jmv.inventory.requests.approve','New JMV stock request',"{$record->request_no} is waiting for approval.");return back()->with('success','Stock request submitted for approval.');}
 public function approve(Request $r,JmvStockRequest $stockRequest){$this->authorize('jmv.inventory.requests.approve');$this->ensure($stockRequest);$d=$r->validate(['approval_remarks'=>'nullable|string|max:2000']);abort_unless($stockRequest->status==='PENDING',422,'Only pending requests can be approved.');$stockRequest->update(['status'=>'APPROVED','approval_remarks'=>$d['approval_remarks']??null,'approved_by'=>auth()->id(),'approved_at'=>now()]);$stockRequest->requester?->notify(new JmvInventoryNotification('Stock request approved',"{$stockRequest->request_no} was approved and is ready for release.",route('jmv.requests.index')));return back()->with('success','Stock request approved.');}
 public function reject(Request $r,JmvStockRequest $stockRequest){$this->authorize('jmv.inventory.requests.approve');$this->ensure($stockRequest);$d=$r->validate(['approval_remarks'=>'required|string|max:2000']);abort_unless($stockRequest->status==='PENDING',422,'Only pending requests can be returned.');$stockRequest->update(['status'=>'REJECTED','approval_remarks'=>$d['approval_remarks'],'approved_by'=>auth()->id(),'approved_at'=>now()]);$stockRequest->requester?->notify(new JmvInventoryNotification('Stock request returned',"{$stockRequest->request_no} was returned: {$d['approval_remarks']}",route('jmv.requests.index')));return back()->with('success','Stock request returned to the requester.');}
 public function release(JmvStockRequest $stockRequest){$this->authorize('jmv.inventory.movements.manage');$this->ensure($stockRequest);DB::transaction(function()use($stockRequest){$locked=JmvStockRequest::whereKey($stockRequest->id)->lockForUpdate()->firstOrFail();abort_unless($locked->status==='APPROVED',422,'Only approved requests can be released.');foreach($locked->items as $line){$item=ItemInventoryHeader::whereKey($line->item_inventory_header_id)->lockForUpdate()->firstOrFail();$balance=JmvInventoryBalance::where('item_inventory_header_id',$item->id)->where('location_id',$line->location_id)->lockForUpdate()->firstOrFail();if($balance->quantity<$line->quantity)throw ValidationException::withMessages(['stock'=>"Insufficient stock for {$item->item_name}."]);$before=$item->stock_on_hand;$after=$before-$line->quantity;$item->update(['stock_on_hand'=>$after,'updated_by'=>auth()->id()]);$balance->decrement('quantity',$line->quantity);$tx=ItemInventoryTransaction::create(['item_inventory_header_id'=>$item->id,'location_id'=>$line->location_id,'type'=>'OUT','movement_kind'=>'REQUEST','quantity'=>$line->quantity,'balance_before'=>$before,'balance_after'=>$after,'reference_no'=>$locked->request_no,'issued_to'=>trim($locked->requester->name.' '.$locked->requester->lastname),'department_id'=>$locked->department_id,'purpose'=>$locked->purpose,'transacted_at'=>now(),'created_by'=>auth()->id(),'approved_by'=>$locked->approved_by,'approved_at'=>$locked->approved_at]);$line->update(['approved_quantity'=>$line->quantity,'item_inventory_transaction_id'=>$tx->id]);JmvInventoryAudit::create(['item_inventory_header_id'=>$item->id,'item_inventory_transaction_id'=>$tx->id,'user_id'=>auth()->id(),'action'=>'request_released','changes'=>['request_no'=>$locked->request_no],'ip_address'=>request()->ip(),'user_agent'=>request()->userAgent(),'created_at'=>now()]);}$locked->update(['status'=>'RELEASED','released_by'=>auth()->id(),'released_at'=>now()]);});$stockRequest->requester?->notify(new JmvInventoryNotification('Stock released',"{$stockRequest->request_no} was released by the warehouse.",route('jmv.requests.index')));return back()->with('success','Requested stock released and inventory updated.');}
 private function notify(string $permission,string $subject,string $message):void{$users=User::where('division_id',$this->divisionId())->where('status',true)->whereHas('position.permissions',fn($q)=>$q->where('slug',$permission))->get();try{Notification::send($users,new JmvInventoryNotification($subject,$message,route('jmv.requests.index')));}catch(\Throwable $e){report($e);}}
 private function can(string $p):bool{return auth()->user()->isSystemAdministrator()||auth()->user()->hasPermission($p);}private function authorize(string $p):void{abort_unless($this->can($p),403);}private function divisionId():int{return(int)Division::whereRaw('LOWER(name) = ?',['jmv'])->value('id');}private function ensure(JmvStockRequest $r):void{abort_unless((int)$r->division_id===$this->divisionId(),404);}private function code():string{do{$c='JREQ-'.now()->format('ymd').'-'.strtoupper(bin2hex(random_bytes(2)));}while(JmvStockRequest::where('request_no',$c)->exists());return$c;}
}
